function gscoop {
[CmdletBinding(SupportsShouldProcess = $true, ConfirmImpact = 'Medium')]
    param()

    $ErrorActionPreference = 'Stop'
    $scoopDir = Join-Path $env:LOCALAPPDATA 'Scoop'
    $scoopGlobalDir = Join-Path $env:ProgramData 'Scoop\apps'
    $legacyScoopShim = 'F:\backup\windowsapps\installed\scoop\shims'
    $scoopShimDir = Join-Path $scoopDir 'shims'

    function Assert-GscoopNtfsPath {
        param([Parameter(Mandatory = $true)][string]$Path)

        $root = [IO.Path]::GetPathRoot($Path)
        if ([string]::IsNullOrWhiteSpace($root)) {
            throw "Cannot determine a drive root for '$Path'."
        }
        $deviceId = $root.TrimEnd('\')
        $disk = Get-CimInstance -ClassName Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $deviceId)
        if ($null -eq $disk -or $disk.FileSystem -ne 'NTFS') {
            $fileSystem = if ($disk) { $disk.FileSystem } else { 'unknown' }
            throw "Scoop requires NTFS junction support. '$Path' is on '$deviceId' ($fileSystem)."
        }
    }

    function Invoke-GscoopScoop {
        param([Parameter(Mandatory = $true)][string[]]$Arguments)

        & $script:scoopExecutable @Arguments
        $succeeded = $?
        $exitCode = if ($null -eq $global:LASTEXITCODE) { 0 } else { [int]$global:LASTEXITCODE }
        if (-not $succeeded -or $exitCode -ne 0) {
            throw "scoop $($Arguments -join ' ') failed with exit code $exitCode."
        }
    }

    Assert-GscoopNtfsPath -Path $scoopDir
    Assert-GscoopNtfsPath -Path $scoopGlobalDir

    if ($PSCmdlet.ShouldProcess('user environment', "route Scoop to '$scoopDir'")) {
        [Environment]::SetEnvironmentVariable('SCOOP', $scoopDir, 'User')
        [Environment]::SetEnvironmentVariable('SCOOP_GLOBAL', $scoopGlobalDir, 'User')
        $env:SCOOP = $scoopDir
        $env:SCOOP_GLOBAL = $scoopGlobalDir

        $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
        $segments = @($userPath -split ';' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        $segments = @($segments | Where-Object {
            -not [string]::Equals($_.TrimEnd('\'), $legacyScoopShim.TrimEnd('\'), [StringComparison]::OrdinalIgnoreCase) -and
            -not [string]::Equals($_.TrimEnd('\'), $scoopShimDir.TrimEnd('\'), [StringComparison]::OrdinalIgnoreCase)
        })
        $updatedPath = @($scoopShimDir) + $segments
        [Environment]::SetEnvironmentVariable('Path', ($updatedPath -join ';'), 'User')
        $env:Path = $scoopShimDir + ';' + (($env:Path -split ';' | Where-Object {
            -not [string]::Equals($_.TrimEnd('\'), $legacyScoopShim.TrimEnd('\'), [StringComparison]::OrdinalIgnoreCase) -and
            -not [string]::Equals($_.TrimEnd('\'), $scoopShimDir.TrimEnd('\'), [StringComparison]::OrdinalIgnoreCase)
        }) -join ';')
    }

    $candidates = @(
        (Join-Path $scoopShimDir 'scoop.cmd')
        (Join-Path $scoopShimDir 'scoop.ps1')
    ) | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf }
    $script:scoopExecutable = $candidates | Select-Object -First 1

    if (-not $script:scoopExecutable) {
        if (-not $PSCmdlet.ShouldProcess($scoopDir, 'install Scoop')) {
            return
        }

        $installer = Invoke-RestMethod -Uri 'https://get.scoop.sh'
        & ([scriptblock]::Create($installer)) -RunAsAdmin -ScoopDir $scoopDir -ScoopGlobalDir $scoopGlobalDir
        $installSucceeded = $?
        $installExitCode = if ($null -eq $global:LASTEXITCODE) { 0 } else { [int]$global:LASTEXITCODE }
        if (-not $installSucceeded -or $installExitCode -ne 0) {
            throw "Scoop installation failed with exit code $installExitCode."
        }

        $candidates = @(
            (Join-Path $scoopShimDir 'scoop.cmd')
            (Join-Path $scoopShimDir 'scoop.ps1')
        ) | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf }
        $script:scoopExecutable = $candidates | Select-Object -First 1
    }

    if (-not $script:scoopExecutable) {
        throw "Scoop was not found after setup. Expected a shim beneath '$scoopShimDir'."
    }

    if ($PSCmdlet.ShouldProcess('git', 'install global Scoop package')) {
        Invoke-GscoopScoop -Arguments @('install', 'git', '-g')
    }

    $buckets = @(Invoke-GscoopScoop -Arguments @('bucket', 'list'))
    $hasScoopApps = @($buckets | Where-Object { $_ -match '^\s*scoop-apps(?:\s|$)' }).Count -gt 0
    if (-not $hasScoopApps -and $PSCmdlet.ShouldProcess('scoop-apps', 'add Scoop bucket')) {
        Invoke-GscoopScoop -Arguments @('bucket', 'add', 'scoop-apps', 'https://github.com/Ash258/Scoop-Ash258')
    }
}

if ($MyInvocation.InvocationName -ne '.') {
    & 'gscoop' @args
}
